{
  "tasks": [
    {
      "claim_id": "c1",
      "verifiable": true,
      "task": "Provide a test case where the input formula starts with '=' and does not contain 'INDIRECT' or 'HYPERLINK' (in any case), and verify that the tool accepts it without raising an error.",
      "reason": "This tests the core behavior of the tool as described in the summary: acceptance of safe formulas and rejection of unsafe ones. A successful pass confirms the tool correctly validates and accepts safe inputs."
    },
    {
      "claim_id": "c2",
      "verifiable": true,
      "task": "Submit a formula string that starts with '=' and contains 'INDIRECT' in uppercase or lowercase, and observe whether the tool raises a ValueError with a descriptive message indicating the presence of an unsafe function.",
      "reason": "This verifies the functionality of the tool to detect and block unsafe functions during input validation, directly testing the claim about safety checks in the input."
    },
    {
      "claim_id": "c3",
      "verifiable": true,
      "task": "Submit a formula string that does not start with '=' (e.g., 'A1+B1') and confirm that the tool raises a ValueError indicating the formula must start with '='.",
      "reason": "This validates the prefix validation mechanism as specified in the claim, ensuring the tool enforces the '=' requirement as a mandatory condition."
    },
    {
      "claim_id": "c4",
      "verifiable": true,
      "task": "Submit a formula such as '=INDIRECT(A1)' or '=HYPERLINK(\"url\", \"link\")' and confirm that the tool raises a ValueError explicitly mentioning the presence of 'INDIRECT' or 'HYPERLINK'.",
      "reason": "This directly tests the claim that the tool blocks formulas containing 'INDIRECT' or 'HYPERLINK' in uppercase, ensuring the detection is case-insensitive and robust against variations in capitalization."
    },
    {
      "claim_id": "c5",
      "verifiable": true,
      "task": "Submit a valid formula like '=A1+B1' and confirm that the tool returns the exact formula string without modification, and that no error is raised.",
      "reason": "This verifies the output behavior when all validations pass: the tool correctly returns the accepted formula as expected, confirming the success path of the validation logic."
    },
    {
      "claim_id": "c6",
      "verifiable": true,
      "task": "Submit a formula with an incorrect schema (e.g., missing 'formula' property or a non-string value) and observe whether the tool raises a validation error consistent with the input schema definition.",
      "reason": "This tests the schema enforcement for the 'formula' field, ensuring the tool adheres to the defined input structure and rejects malformed inputs as per the schema specification."
    }
  ]
}
